window.LZ_I18N={"en": {"nav.vision": "Vision", "nav.places": "Places", "nav.buyers": "Buyers", "nav.investors": "Investors", "nav.join": "Request access", "nav.login": "Sign in", "nav.home": "Back to Leveza", "cover.kicker": "Sesimbra · Portugal's Atlantic coast", "cover.cap": "Between two waters", "motto": "We conceive destinations where great design, longevity, and coastal ease come together — places built around how people actually want to&nbsp;feel.", "cover.sub": "Seven houses among the pines. By registration only.", "word.kicker": "The word", "word.phon": "Portuguese", "word.pos": "noun · feminine", "word.def": "Lightness; the quality of carrying little weight. Ease of body and of mind.", "word.ex": "“a leveza de um corpo depois do mar” — the lightness of a body after the sea", "lux.h": "Luxury,<br><em>weighed differently.</em>", "lux.p": "Leveza is luxury measured by what it removes: weight, noise, effort, heat. The feeling of a body after a swim. Of a house that asks nothing of you. Of a day with no traffic in it. Everything in it is of the highest quality, and none of it announces itself — the stone, the lime, the linen, the silence.", "std.kicker": "The four standards", "std.h": "A place, told in <em>four hours</em><br>of the same long day.", "agua.s": "07:04 · water", "agua.p": "The first lengths, before the phone finds you. Water built for swimming, warm enough for November.", "sombra.s": "13:00 · shade", "sombra.p": "Deep loggias, lime walls that breathe, every tree kept. The place pushes you outside, even in August.", "mesa.s": "19:30 · the table", "mesa.p": "The kitchen as the largest room. A long table, half of it outdoors.", "sono.s": "23:10 · sleep", "sono.p": "Bedrooms facing east, quiet zoning, light that warms as the evening goes. Sleep better than at home.", "std.note": "Fixed in every architect's brief before a single line is drawn — and proven at handover with one page of numbers per house. <i>Design choices, not promises.</i>", "coast.kicker": "Coastal ease", "coast.h": "Pines, dunes, the Atlantic.<br><em>Forty minutes from Lisbon, still quiet.</em>", "coast.p": "South of the Tagus the coast turns to umbrella pines, a lagoon that meets the ocean, and a beach village that still closes for lunch. Leveza begins here, where this landscape runs closest to the capital: the same light, the same trees, a fraction of the distance.", "places.kicker": "The first neighbourhoods", "places.h": "Lagoa Pines first,<br><em>Meco Dunes to follow.</em>", "lagoa.s": "Lagoa de Albufeira · seven houses", "lagoa.p": "Among umbrella pines, in the village between the lagoon and the ocean. White lime, a reed-shaded loggia, a pool built for lengths.", "meco.s": "Aldeia do Meco", "meco.soon": "Coming soon", "meco.p": "Near the beach village, among the dunes. In preparation; registered guests hear first.", "places.note": "Lagoa Pines is in design and subject to planning permission. Plans, sizes and a price indication are shared with registered buyers.", "not.kicker": "For the avoidance of doubt", "not.1": "a resort", "not.2": "a clinic", "not.3": "a wellness brand", "not.4": "gated", "not.5": "a reception desk", "not.h": "Small neighbourhoods.<br><em>A place, not a facility.</em>", "aud.kicker": "Dentro · behind the door", "aud.h": "More, for those<br><em>who ask.</em>", "buy.t": "For buyers", "buy.p": "You are looking for a house on this coast, to live in or to return to.", "buy.li1": "Dentro: the house room by room, and its materials", "buy.li2": "Floor plans, section, plot, sizes and a price indication", "buy.li3": "The four standards, written as numbers", "buy.li4": "First notice when houses are released", "buy.note": "Open as soon as you confirm your e-mail address.", "buy.cta": "Register as a buyer", "inv.t": "For investors", "inv.p": "Leveza is developed by ZVMS, Lda, a Portuguese company based in Lisbon. A small number of private investors take part.", "inv.li1": "The investor presentation", "inv.li2": "Project figures", "inv.li3": "Structure, security and risks", "inv.li4": "A personal conversation with the founders", "inv.note": "Every request is reviewed personally before access is given. Information for investors is provided on request only; nothing on this page is an offer.", "inv.cta": "Request investor access", "form.kicker": "Register", "form.h": "Tell us<br><em>who is asking.</em>", "form.p": "We send one e-mail with a link. Click it and the door opens — no password to remember.", "f.name": "Name", "f.email": "E-mail", "f.iam": "I am", "f.buyer": "a buyer — I'm looking for a house", "f.investor": "an investor — I'd like to take part", "f.country": "Country", "f.msg": "Anything you'd like us to know (optional)", "f.consent": "I agree that Leveza keeps these details to contact me about its projects. <a href=\"#privacy\">Privacy note</a>.", "f.submit": "Send confirmation e-mail", "f.sending": "Sending…", "f.have": "Already registered? <a href=\"#acesso\">Sign in</a>", "f.err.required": "Please fill in your name and a valid e-mail address, and tick the box.", "f.err.generic": "That didn't go through. Please try again in a minute.", "f.err.config": "Registration is not switched on yet.", "sent.h": "Check your inbox.", "sent.buyer": "We sent a link to <b>{email}</b>. Click it to confirm your address — the buyers' side opens straight away.", "sent.investor": "We sent a link to <b>{email}</b>. Click it to confirm your address. We review every investor request personally and write to you when the investor side is open; until then you can already see the buyers' side.", "foot.1": "A development by ZVMS, Lda · Lisbon", "foot.2": "Lagoa Pines · Meco Dunes (coming soon) · Sesimbra, Portugal", "foot.3": "Photographs are mood images. All plans are concepts, subject to planning permission.", "foot.privacy": "Privacy", "acc.kicker": "Dentro · for registered guests", "login.h": "Sign in", "login.p": "Enter your e-mail address and we'll send you a link. No password.", "login.submit": "Send me a link", "login.sent": "If this address is registered, a link is on its way.", "login.new": "Not registered yet? <a href=\"#register\">Request access</a>", "acc.hello": "Welcome, {name}.", "acc.hello0": "Welcome.", "acc.logout": "Sign out", "acc.loading": "One moment…", "acc.empty": "This part is being prepared.", "acc.error": "We couldn't load your access. Sign out and use the link in your e-mail again.", "acc.blocked": "This access has been closed. Write to us if you think that is a mistake.", "tab.buyers": "The house", "tab.dentro": "Dentro", "tab.investors": "Investors", "pend.h": "Your investor request is with us.", "pend.p": "We review each request personally and will e-mail you as soon as the investor side is open. The buyers' side is already yours to read.", "decl.p": "We haven't been able to open the investor side for this request. Write to us if you'd like to talk it through.", "reqinv.h": "Would you like to take part as an investor?", "reqinv.p": "The investor side holds the presentation, the project figures and the structure. We review each request personally.", "reqinv.btn": "Request investor access", "priv.h": "Privacy note", "priv.1": "<b>Who.</b> Leveza is a development by ZVMS, Lda (Avenida Arantes e Oliveira 3, R/C, 1900-221 Lisbon, Portugal; company number 519729544). ZVMS is responsible for the personal data collected on this website.", "priv.2": "<b>What and why.</b> When you register we keep your name, e-mail address, country, language, whether you registered as a buyer or an investor, your message and the time you gave consent. We use them to give you access to the closed part of this site and to contact you about Leveza's projects. The legal basis is your consent.", "priv.3": "<b>Where and how long.</b> The data is stored with our hosting, database and e-mail providers within the European Union and is not passed on to anyone else. We keep it until you withdraw your consent, and no longer than two years after our last contact.", "priv.4": "<b>Your rights.</b> You can ask to see, correct or delete your data, or withdraw your consent, at any time by writing to <a href=\"mailto:aria@znd-ventures.com\">aria@znd-ventures.com</a>. You may also lodge a complaint with the Portuguese data protection authority (CNPD) or the authority in your own country."}, "nl": {"nav.vision": "Visie", "nav.places": "Plekken", "nav.buyers": "Kopers", "nav.investors": "Investeerders", "nav.join": "Toegang aanvragen", "nav.login": "Inloggen", "nav.home": "Terug naar Leveza", "cover.kicker": "Sesimbra · de Atlantische kust van Portugal", "cover.cap": "Tussen twee wateren", "motto": "Wij ontwerpen plekken waar goed ontwerp, een lang leven en het gemak van de kust samenkomen — gebouwd rond hoe mensen zich werkelijk willen&nbsp;voelen.", "cover.sub": "Zeven huizen tussen de dennen. Alleen na inschrijving.", "word.kicker": "Het woord", "word.phon": "Portugees", "word.pos": "zelfstandig naamwoord · vrouwelijk", "word.def": "Lichtheid; de eigenschap weinig gewicht te dragen. Gemak van lichaam en geest.", "word.ex": "“a leveza de um corpo depois do mar” — de lichtheid van een lichaam na de zee", "lux.h": "Luxe,<br><em>anders gewogen.</em>", "lux.p": "Leveza is luxe gemeten aan wat ze wegneemt: gewicht, lawaai, moeite, hitte. Het gevoel van een lichaam na het zwemmen. Van een huis dat niets van je vraagt. Van een dag zonder verkeer. Alles is van de hoogste kwaliteit en niets dringt zich op — de steen, de kalk, het linnen, de stilte.", "std.kicker": "De vier standaarden", "std.h": "Een plek, verteld in <em>vier uren</em><br>van dezelfde lange dag.", "agua.s": "07:04 · water", "agua.p": "De eerste banen, voordat je telefoon je vindt. Water om in te zwemmen, warm genoeg voor november.", "sombra.s": "13:00 · schaduw", "sombra.p": "Diepe loggia's, kalkmuren die ademen, elke boom blijft staan. De plek duwt je naar buiten, ook in augustus.", "mesa.s": "19:30 · de tafel", "mesa.p": "De keuken als grootste kamer. Een lange tafel, voor de helft buiten.", "sono.s": "23:10 · slaap", "sono.p": "Slaapkamers op het oosten, rust in de indeling, licht dat warmer wordt naarmate de avond vordert. Beter slapen dan thuis.", "std.note": "Vastgelegd in elke opdracht aan de architect voordat er één lijn is getekend — en bij oplevering aangetoond met één pagina cijfers per huis. <i>Ontwerpkeuzes, geen beloftes.</i>", "coast.kicker": "Het gemak van de kust", "coast.h": "Dennen, duinen, de Atlantische Oceaan.<br><em>Veertig minuten van Lissabon, nog altijd stil.</em>", "coast.p": "Ten zuiden van de Taag gaat de kust over in parasoldennen, een lagune die de oceaan raakt en een stranddorp dat nog sluit voor de lunch. Leveza begint hier, waar dit landschap het dichtst bij de hoofdstad komt: hetzelfde licht, dezelfde bomen, een fractie van de afstand.", "places.kicker": "De eerste buurten", "places.h": "Eerst Lagoa Pines,<br><em>daarna Meco Dunes.</em>", "lagoa.s": "Lagoa de Albufeira · zeven huizen", "lagoa.p": "Tussen de parasoldennen, in het dorp tussen de lagune en de oceaan. Witte kalk, een loggia onder riet, een bad om banen in te trekken.", "meco.s": "Aldeia do Meco", "meco.soon": "Binnenkort", "meco.p": "Bij het stranddorp, tussen de duinen. In voorbereiding; ingeschreven gasten horen het als eerste.", "places.note": "Lagoa Pines is in ontwerp en onder voorbehoud van vergunning. Plattegronden, maten en een prijsindicatie delen we met ingeschreven kopers.", "not.kicker": "Voor alle duidelijkheid", "not.1": "een resort", "not.2": "een kliniek", "not.3": "een wellnessmerk", "not.4": "een hek eromheen", "not.5": "een receptie", "not.h": "Kleine buurten.<br><em>Een plek, geen voorziening.</em>", "aud.kicker": "Dentro · achter de deur", "aud.h": "Meer, voor wie<br><em>erom vraagt.</em>", "buy.t": "Voor kopers", "buy.p": "Je zoekt een huis aan deze kust, om te wonen of om naar terug te keren.", "buy.li1": "Dentro: het huis kamer voor kamer, en de materialen", "buy.li2": "Plattegronden, doorsnede, kavel, maten en een prijsindicatie", "buy.li3": "De vier standaarden, uitgeschreven in cijfers", "buy.li4": "Als eerste bericht wanneer huizen vrijkomen", "buy.note": "Open zodra je je e-mailadres hebt bevestigd.", "buy.cta": "Inschrijven als koper", "inv.t": "Voor investeerders", "inv.p": "Leveza wordt ontwikkeld door ZVMS, Lda, een Portugese vennootschap gevestigd in Lissabon. Een klein aantal particuliere investeerders doet mee.", "inv.li1": "De investeerderspresentatie", "inv.li2": "Projectcijfers", "inv.li3": "Structuur, zekerheden en risico's", "inv.li4": "Een persoonlijk gesprek met de oprichters", "inv.note": "Elke aanvraag beoordelen we persoonlijk voordat we toegang geven. Informatie voor investeerders verstrekken we alleen op verzoek; niets op deze pagina is een aanbod.", "inv.cta": "Investeerderstoegang aanvragen", "form.kicker": "Inschrijven", "form.h": "Vertel ons<br><em>wie het vraagt.</em>", "form.p": "We sturen één e-mail met een link. Klik erop en de deur gaat open — geen wachtwoord om te onthouden.", "f.name": "Naam", "f.email": "E-mail", "f.iam": "Ik ben", "f.buyer": "koper — ik zoek een huis", "f.investor": "investeerder — ik wil meedoen", "f.country": "Land", "f.msg": "Iets wat we moeten weten (niet verplicht)", "f.consent": "Ik ga ermee akkoord dat Leveza deze gegevens bewaart om contact met mij op te nemen over haar projecten. <a href=\"#privacy\">Privacyverklaring</a>.", "f.submit": "Stuur bevestigingsmail", "f.sending": "Bezig met versturen…", "f.have": "Al ingeschreven? <a href=\"#acesso\">Inloggen</a>", "f.err.required": "Vul je naam en een geldig e-mailadres in en vink het vakje aan.", "f.err.generic": "Dat is niet gelukt. Probeer het over een minuut opnieuw.", "f.err.config": "Inschrijven staat nog niet aan.", "sent.h": "Kijk in je inbox.", "sent.buyer": "We hebben een link gestuurd naar <b>{email}</b>. Klik erop om je adres te bevestigen — de koperskant gaat dan direct open.", "sent.investor": "We hebben een link gestuurd naar <b>{email}</b>. Klik erop om je adres te bevestigen. Elke aanvraag van een investeerder beoordelen we persoonlijk; je krijgt bericht zodra de investeerderskant open is. Tot die tijd kun je de koperskant al bekijken.", "foot.1": "Een ontwikkeling van ZVMS, Lda · Lissabon", "foot.2": "Lagoa Pines · Meco Dunes (binnenkort) · Sesimbra, Portugal", "foot.3": "Foto's zijn sfeerbeelden. Alle plannen zijn concepten, onder voorbehoud van vergunning.", "foot.privacy": "Privacy", "acc.kicker": "Dentro · voor ingeschreven gasten", "login.h": "Inloggen", "login.p": "Vul je e-mailadres in en we sturen je een link. Geen wachtwoord.", "login.submit": "Stuur mij een link", "login.sent": "Als dit adres is ingeschreven, is er een link onderweg.", "login.new": "Nog niet ingeschreven? <a href=\"#register\">Toegang aanvragen</a>", "acc.hello": "Welkom, {name}.", "acc.hello0": "Welkom.", "acc.logout": "Uitloggen", "acc.loading": "Een ogenblik…", "acc.empty": "Dit deel wordt nog voorbereid.", "acc.error": "We konden je toegang niet laden. Log uit en gebruik de link in je e-mail opnieuw.", "acc.blocked": "Deze toegang is gesloten. Laat het ons weten als dat volgens jou niet klopt.", "tab.buyers": "Het huis", "tab.dentro": "Dentro", "tab.investors": "Investeerders", "pend.h": "Je aanvraag als investeerder is binnen.", "pend.p": "We beoordelen elke aanvraag persoonlijk en mailen je zodra de investeerderskant open is. De koperskant kun je alvast lezen.", "decl.p": "We hebben de investeerderskant voor deze aanvraag niet kunnen openen. Laat het weten als je erover wilt praten.", "reqinv.h": "Wil je meedoen als investeerder?", "reqinv.p": "Aan de investeerderskant staan de presentatie, de projectcijfers en de structuur. We beoordelen elke aanvraag persoonlijk.", "reqinv.btn": "Investeerderstoegang aanvragen", "priv.h": "Privacyverklaring", "priv.1": "<b>Wie.</b> Leveza is een ontwikkeling van ZVMS, Lda (Avenida Arantes e Oliveira 3, R/C, 1900-221 Lissabon, Portugal; registratienummer 519729544). ZVMS is verantwoordelijk voor de persoonsgegevens die via deze website worden verzameld.", "priv.2": "<b>Wat en waarom.</b> Bij inschrijving bewaren we je naam, e-mailadres, land, taal, of je je als koper of investeerder hebt ingeschreven, je bericht en het moment waarop je toestemming gaf. We gebruiken die gegevens om je toegang te geven tot het besloten deel van deze site en om contact met je op te nemen over de projecten van Leveza. De grondslag is je toestemming.", "priv.3": "<b>Waar en hoe lang.</b> De gegevens staan bij onze hosting-, database- en e-mailleveranciers binnen de Europese Unie en worden aan niemand anders doorgegeven. We bewaren ze tot je je toestemming intrekt, en niet langer dan twee jaar na ons laatste contact.", "priv.4": "<b>Je rechten.</b> Je kunt op elk moment vragen je gegevens in te zien, te verbeteren of te verwijderen, of je toestemming intrekken, via <a href=\"mailto:aria@znd-ventures.com\">aria@znd-ventures.com</a>. Je kunt ook een klacht indienen bij de Portugese toezichthouder (CNPD) of bij de toezichthouder in je eigen land."}, "pt": {"nav.vision": "Visão", "nav.places": "Lugares", "nav.buyers": "Compradores", "nav.investors": "Investidores", "nav.join": "Pedir acesso", "nav.login": "Entrar", "nav.home": "Voltar a Leveza", "cover.kicker": "Sesimbra · a costa atlântica de Portugal", "cover.cap": "Entre duas águas", "motto": "Concebemos lugares onde o bom desenho, a longevidade e a leveza da costa se encontram — construídos à volta de como as pessoas querem, de facto,&nbsp;sentir-se.", "cover.sub": "Sete casas entre os pinheiros. Apenas por inscrição.", "word.kicker": "A palavra", "word.phon": "português", "word.pos": "substantivo · feminino", "word.def": "Qualidade do que é leve, do que tem pouco peso. Desafogo do corpo e do espírito.", "word.ex": "“a leveza de um corpo depois do mar”", "lux.h": "Luxo,<br><em>pesado de outra forma.</em>", "lux.p": "Leveza é o luxo medido pelo que retira: peso, ruído, esforço, calor. A sensação de um corpo depois de nadar. De uma casa que não pede nada. De um dia sem trânsito. Tudo é da mais alta qualidade e nada se anuncia — a pedra, a cal, o linho, o silêncio.", "std.kicker": "Os quatro padrões", "std.h": "Um lugar, contado em <em>quatro horas</em><br>do mesmo longo dia.", "agua.s": "07:04 · água", "agua.p": "As primeiras braçadas, antes de o telefone o encontrar. Água feita para nadar, morna até em novembro.", "sombra.s": "13:00 · sombra", "sombra.p": "Alpendres fundos, paredes de cal que respiram, todas as árvores mantidas. O lugar empurra-o para fora, mesmo em agosto.", "mesa.s": "19:30 · a mesa", "mesa.p": "A cozinha como a maior divisão. Uma mesa comprida, metade dela cá fora.", "sono.s": "23:10 · sono", "sono.p": "Quartos virados a nascente, zonas de silêncio, luz que aquece ao cair da noite. Dormir melhor do que em casa.", "std.note": "Fixados no programa de cada arquitecto antes do primeiro traço — e comprovados na entrega com uma página de números por casa. <i>Escolhas de projecto, não promessas.</i>", "coast.kicker": "A leveza da costa", "coast.h": "Pinhal, dunas, o Atlântico.<br><em>A quarenta minutos de Lisboa, ainda em silêncio.</em>", "coast.p": "A sul do Tejo a costa faz-se de pinheiros-mansos, de uma lagoa que encontra o mar e de uma aldeia de praia que ainda fecha ao almoço. Leveza começa aqui, onde esta paisagem chega mais perto da capital: a mesma luz, as mesmas árvores, uma fracção da distância.", "places.kicker": "Os primeiros bairros", "places.h": "Primeiro Lagoa Pines,<br><em>depois Meco Dunes.</em>", "lagoa.s": "Lagoa de Albufeira · sete casas", "lagoa.p": "Entre pinheiros-mansos, na aldeia entre a lagoa e o mar. Cal branca, um alpendre à sombra do caniço, uma piscina feita para nadar.", "meco.s": "Aldeia do Meco", "meco.soon": "Em breve", "meco.p": "Junto à aldeia de praia, entre as dunas. Em preparação; os convidados inscritos são os primeiros a saber.", "places.note": "Lagoa Pines está em fase de projecto e sujeito a licenciamento. Plantas, áreas e uma indicação de preço são partilhadas com compradores inscritos.", "not.kicker": "Para que não haja dúvidas", "not.1": "um resort", "not.2": "uma clínica", "not.3": "uma marca de bem-estar", "not.4": "um condomínio fechado", "not.5": "uma recepção", "not.h": "Pequenos bairros.<br><em>Um lugar, não um equipamento.</em>", "aud.kicker": "Dentro · atrás da porta", "aud.h": "Mais, para quem<br><em>pergunta.</em>", "buy.t": "Para compradores", "buy.p": "Procura uma casa nesta costa, para viver ou para regressar.", "buy.li1": "Dentro: a casa divisão a divisão, e os seus materiais", "buy.li2": "Plantas, corte, lote, áreas e uma indicação de preço", "buy.li3": "Os quatro padrões, escritos em números", "buy.li4": "Aviso em primeira mão quando as casas forem lançadas", "buy.note": "Disponível assim que confirmar o seu e-mail.", "buy.cta": "Inscrever-me como comprador", "inv.t": "Para investidores", "inv.p": "Leveza é desenvolvida pela ZVMS, Lda, sociedade portuguesa com sede em Lisboa. Participa um pequeno número de investidores privados.", "inv.li1": "A apresentação para investidores", "inv.li2": "Números do projecto", "inv.li3": "Estrutura, garantias e riscos", "inv.li4": "Uma conversa pessoal com os fundadores", "inv.note": "Cada pedido é analisado pessoalmente antes de dar acesso. A informação para investidores só é prestada a pedido; nada nesta página constitui uma oferta.", "inv.cta": "Pedir acesso de investidor", "form.kicker": "Inscrição", "form.h": "Diga-nos<br><em>quem pergunta.</em>", "form.p": "Enviamos um e-mail com uma ligação. Clique e a porta abre-se — sem palavra-passe para decorar.", "f.name": "Nome", "f.email": "E-mail", "f.iam": "Sou", "f.buyer": "comprador — procuro uma casa", "f.investor": "investidor — gostaria de participar", "f.country": "País", "f.msg": "Algo que queira dizer-nos (opcional)", "f.consent": "Aceito que a Leveza guarde estes dados para me contactar sobre os seus projectos. <a href=\"#privacy\">Nota de privacidade</a>.", "f.submit": "Enviar e-mail de confirmação", "f.sending": "A enviar…", "f.have": "Já está inscrito? <a href=\"#acesso\">Entrar</a>", "f.err.required": "Indique o seu nome e um e-mail válido e assinale a caixa.", "f.err.generic": "Não foi possível enviar. Tente de novo dentro de um minuto.", "f.err.config": "A inscrição ainda não está activa.", "sent.h": "Veja a sua caixa de entrada.", "sent.buyer": "Enviámos uma ligação para <b>{email}</b>. Clique para confirmar o endereço — a área de compradores abre de imediato.", "sent.investor": "Enviámos uma ligação para <b>{email}</b>. Clique para confirmar o endereço. Analisamos pessoalmente cada pedido de investidor e escrevemos-lhe quando a área de investidores estiver aberta; até lá já pode ver a área de compradores.", "foot.1": "Um projecto da ZVMS, Lda · Lisboa", "foot.2": "Lagoa Pines · Meco Dunes (em breve) · Sesimbra, Portugal", "foot.3": "As fotografias são imagens de ambiente. Todos os planos são conceitos, sujeitos a licenciamento.", "foot.privacy": "Privacidade", "acc.kicker": "Dentro · para convidados inscritos", "login.h": "Entrar", "login.p": "Indique o seu e-mail e enviamos-lhe uma ligação. Sem palavra-passe.", "login.submit": "Enviar ligação", "login.sent": "Se este endereço estiver inscrito, a ligação vai a caminho.", "login.new": "Ainda não está inscrito? <a href=\"#register\">Pedir acesso</a>", "acc.hello": "Bem-vindo, {name}.", "acc.hello0": "Bem-vindo.", "acc.logout": "Sair", "acc.loading": "Um momento…", "acc.empty": "Esta parte está a ser preparada.", "acc.error": "Não foi possível carregar o seu acesso. Saia e volte a usar a ligação do e-mail.", "acc.blocked": "Este acesso foi encerrado. Escreva-nos se achar que é um engano.", "tab.buyers": "A casa", "tab.dentro": "Dentro", "tab.investors": "Investidores", "pend.h": "Recebemos o seu pedido de investidor.", "pend.p": "Analisamos pessoalmente cada pedido e enviamos-lhe um e-mail assim que a área de investidores estiver aberta. A área de compradores já pode ser consultada.", "decl.p": "Não nos foi possível abrir a área de investidores para este pedido. Escreva-nos se quiser conversar.", "reqinv.h": "Gostaria de participar como investidor?", "reqinv.p": "Na área de investidores estão a apresentação, os números dos projectos e a estrutura. Analisamos cada pedido pessoalmente.", "reqinv.btn": "Pedir acesso de investidor", "priv.h": "Nota de privacidade", "priv.1": "<b>Quem.</b> Leveza é um projecto da ZVMS, Lda (Avenida Arantes e Oliveira, n.º 3, R/C, 1900-221 Lisboa; NIPC 519729544). A ZVMS é responsável pelos dados pessoais recolhidos neste sítio.", "priv.2": "<b>O quê e porquê.</b> Ao inscrever-se guardamos o seu nome, e-mail, país, língua, se se inscreveu como comprador ou investidor, a sua mensagem e o momento do consentimento. Usamos estes dados para lhe dar acesso à área reservada deste sítio e para o contactar sobre os projectos da Leveza. O fundamento é o seu consentimento.", "priv.3": "<b>Onde e durante quanto tempo.</b> Os dados ficam alojados nos nossos fornecedores de alojamento, base de dados e correio electrónico na União Europeia e não são transmitidos a mais ninguém. Conservamo-los até retirar o consentimento e nunca mais de dois anos após o último contacto.", "priv.4": "<b>Os seus direitos.</b> Pode a qualquer momento pedir para consultar, corrigir ou apagar os seus dados, ou retirar o consentimento, escrevendo para <a href=\"mailto:aria@znd-ventures.com\">aria@znd-ventures.com</a>. Pode também apresentar queixa à CNPD ou à autoridade do seu país."}};
